<script setup>import {ref} from 'vue';import AdminShell from '../../components/AdminShell.vue';import StatusBadge from '../../components/StatusBadge.vue';import {receivables,payables} from '../../api/mock';const tab=ref('运行中实例')</script>
<template><AdminShell><template #title>流程实例</template><div class="page-heading"><div><p>PROCESS INSTANCES</p><h1>流程实例</h1><span>从发起、流转、催办到归档的全程可追溯实例台账</span></div><div><button class="button secondary">导出实例</button><button class="button primary">＋ 发起流程</button></div></div>
<section class="settlement-summary"><article><span>运行中实例</span><b>199 个</b><small>12 类流程 · 48 个节点</small></article><article><span>今日已办结</span><b>331 个</b><small class="positive">较昨日同期 +8.4%</small></article><article class="alert"><span>已超时实例</span><b>3 个</b><small>最长超时 4 小时 12 分</small></article><article><span>平均处理时长</span><b>6.8 小时</b><small>较上月缩短 1.2 小时</small></article><div><span>本月 SLA 达标率</span><b>92.4%</b><i><em style="width:92.4%"></em></i></div></section>
<div class="ledger-tabs"><button :class="{active:tab==='运行中实例'}" @click="tab='运行中实例'">运行中实例 <b>199</b></button><button :class="{active:tab==='已办实例'}" @click="tab='已办实例'">任务队列 <b>4</b></button><button>我发起的</button><button>抄送我的</button><label>⌕ <input placeholder="搜索实例、流程或发起人"/></label></div>
<section v-if="tab==='运行中实例'" class="card ledger"><header><div><h2>活跃流程实例</h2><p>数据更新于 16:05</p></div><div class="filters"><button>全部流程 ⌄</button><button>时效状态 ⌄</button></div></header><table><thead><tr><th>实例编号 / 业务摘要</th><th>流程类型</th><th>当前耗时</th><th>节点耗时</th><th>剩余 SLA</th><th>截止时间</th><th>当前处理人</th><th>状态</th></tr></thead><tbody><tr v-for="x in receivables" :key="x.no"><td><b>{{x.no}}</b><small>{{x.source}}</small></td><td>{{x.customer}}</td><td>{{x.amount.toFixed(1)}} 小时</td><td>{{x.received.toFixed(1)}} 小时</td><td><b>{{Math.max(x.amount-x.received,0).toFixed(1)}} 小时</b></td><td :class="{'danger-text':x.status==='已逾期'}">{{x.due}}</td><td><span class="person">{{x.owner[0]}}</span>{{x.owner}}</td><td><StatusBadge :value="x.status"/></td></tr></tbody></table></section>
<section v-else class="card ledger"><header><div><h2>当前任务队列</h2><p>按 SLA 截止时间排序</p></div></header><table><thead><tr><th>任务编号 / 来源</th><th>任务名称</th><th>预计工时</th><th>已用工时</th><th>剩余工时</th><th>截止时间</th><th>发起人</th><th>状态</th></tr></thead><tbody><tr v-for="x in payables" :key="x.no"><td><b>{{x.no}}</b><small>{{x.source}}</small></td><td>{{x.supplier}}</td><td>{{x.amount.toFixed(1)}} h</td><td>{{x.paid.toFixed(1)}} h</td><td><b>{{(x.amount-x.paid).toFixed(1)}} h</b></td><td>{{x.due}}</td><td>{{x.applicant}}</td><td><StatusBadge :value="x.status"/></td></tr></tbody></table></section>
</AdminShell></template>
